def matrix(index: ac.u4) -> ac.table[16, Row16]:
    words = operands()
    base: ac.u8 = index
    base = (base | 0) << 4
    return (
        words[base + 0],
        words[base + 1],
        words[base + 2],
        words[base + 3],
        words[base + 4],
        words[base + 5],
        words[base + 6],
        words[base + 7],
        words[base + 8],
        words[base + 9],
        words[base + 10],
        words[base + 11],
        words[base + 12],
        words[base + 13],
        words[base + 14],
        words[base + 15],
    )


